def parse(tree):
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


def bstIteratorOps(tree, ops):
    val, left, right = parse(tree)
    stack = []
    u = 0
    while u != -1:
        stack.append(u)
        u = left[u]
    out = []
    for op in ops:
        if op == 0:
            u = stack.pop()
            out.append(val[u])
            v = right[u]
            while v != -1:
                stack.append(v)
                v = left[v]
        else:
            out.append(1 if stack else 0)
    return out
